"""Optional summaries and action items for a finished transcript, generated by NVIDIA NIM.

Only transcript text is sent, and only when a caller asks for a mode. Keys come from NVIDIA_NIM_API_KEY_1 to
NVIDIA_NIM_API_KEY_9, in the environment or the project's .env. A key is never returned, logged or stored, and
errors name the variable at most, never its value.
"""
from __future__ import annotations

import json
import logging
import math
import os
import time
import urllib.error
import urllib.request
from typing import Any, Callable

from backend.diarization import _read_env_file

logger = logging.getLogger(__name__)
MODEL_ID = "nvidia/nemotron-3-ultra-550b-a55b"
ENDPOINT = "https://integrate.api.nvidia.com/v1/chat/completions"
MODES = ("summary", "action_items")
MAX_TRANSCRIPT_CHARS = 150_000
TIMEOUT_SECONDS = 120
MAX_RESPONSE_BYTES = 4 * 1024 * 1024
RETRY_DELAY_SECONDS = 1.0
MAX_RETRY_DELAY_SECONDS = 5.0
KEY_VARIABLES = tuple(f"NVIDIA_NIM_API_KEY_{number}" for number in range(1, 10))
NO_KEY_REASON = "AI modes need an NVIDIA NIM key. Add NVIDIA_NIM_API_KEY_1 to .env or the environment to turn them on."
SYSTEM_PROMPTS = {
    "summary": (
        "You summarise a transcript. Use only the transcript and do not add facts from outside it. "
        "If the transcript does not contain what is needed, say so. "
        "Reply with one overview sentence, then 5 to 8 bullet points that start with '- '."
    ),
    "action_items": (
        "You list the action items in a transcript. Use only the transcript and do not add facts from outside it. "
        "For each action item give the owner, the task and the due date. Name an owner only if the transcript names "
        "one, otherwise write 'Owner not named'. Give a due date only if the transcript states one, otherwise leave it out. "
        "Use '- ' bullets. If the transcript contains no action items, or does not say enough to find them, say so."
    ),
}


class NimRequestError(Exception):
    """A failed NIM call. The message is safe to show: it never holds a key, a URL or a local path."""

    def __init__(self, status: int | None, message: str, retry_after: float | None = None):
        super().__init__(message)
        self.status = status
        self.retry_after = retry_after


def configured_keys() -> list[tuple[str, str]]:
    """(variable name, key) pairs in order. A value in the environment takes precedence over .env."""
    keys = []
    for name in KEY_VARIABLES:
        value = os.environ.get(name, "").strip() or _read_env_file(name) or ""
        if value:
            keys.append((name, value))
    return keys


def availability() -> dict[str, Any]:
    reason = None if configured_keys() else NO_KEY_REASON
    return {"available": reason is None, "model": MODEL_ID, "modes": list(MODES), "reason": reason}


def transcript_text(segments: list[dict[str, Any]]) -> str:
    """Plain transcript text, one line per segment, with the speaker label as shown. Timestamps are left out."""
    lines = []
    for segment in segments:
        text = str(segment.get("text") or "").strip()
        if not text:
            continue
        speaker = str(segment.get("speaker") or "").strip()
        lines.append(f"{speaker}: {text}" if speaker else text)
    return "\n".join(lines)


def _fence_safe(transcript: str) -> str:
    """Escape backslashes and double quotes, so no raw quote can close the fence or start a fake message."""
    return transcript.replace("\\", "\\\\").replace('"', '\\"')


def build_messages(mode: str, transcript: str) -> list[dict[str, str]]:
    if mode not in SYSTEM_PROMPTS:
        raise ValueError(f"Unknown AI mode: {mode}")
    return [
        {"role": "system", "content": SYSTEM_PROMPTS[mode]},
        {"role": "user", "content": f"Transcript:\n\"\"\"\n{_fence_safe(transcript)}\n\"\"\""},
    ]


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    """Refuse a 3xx. urlopen would otherwise follow it and keep the Authorization header."""

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        raise urllib.error.HTTPError(req.full_url, code, msg, headers, fp)


_REAL_URLOPEN = urllib.request.urlopen


def _urlopen(request: urllib.request.Request, timeout: float):
    """Open one request without following redirects.

    A substituted urllib.request.urlopen is called unchanged.
    """
    open_url = urllib.request.urlopen
    if open_url is not _REAL_URLOPEN:
        return open_url(request, timeout=timeout)
    opener = urllib.request.build_opener(_NoRedirect)
    return opener.open(request, timeout=timeout)


def send_chat(api_key: str, messages: list[dict[str, str]]) -> str:
    """One chat completion request. The only function that touches the network, so tests replace it."""
    body = json.dumps({"model": MODEL_ID, "messages": messages, "temperature": 0.2,
                       "max_tokens": 4096, "stream": False}).encode("utf-8")
    request = urllib.request.Request(ENDPOINT, data=body, method="POST", headers={
        "Authorization": f"Bearer {api_key}", "Accept": "application/json", "Content-Type": "application/json"})
    try:
        with _urlopen(request, TIMEOUT_SECONDS) as response:
            raw = response.read(MAX_RESPONSE_BYTES + 1)
    except urllib.error.HTTPError as exc:
        try:
            raise NimRequestError(exc.code, f"NVIDIA NIM refused the request (HTTP {exc.code})",
                                  retry_after=_retry_after(exc.headers)) from None
        finally:
            exc.close()
    except (urllib.error.URLError, OSError):
        raise NimRequestError(None, "Could not reach NVIDIA NIM. Check the connection and try again.") from None
    if len(raw) > MAX_RESPONSE_BYTES:
        raise NimRequestError(None, "NVIDIA NIM returned an unexpectedly large response")
    try:
        content = json.loads(raw)["choices"][0]["message"]["content"]
    except (ValueError, KeyError, IndexError, TypeError):
        raise NimRequestError(None, "NVIDIA NIM returned a response that could not be read") from None
    if not isinstance(content, str) or not content.strip():
        raise NimRequestError(None, "NVIDIA NIM returned an empty response")
    return content.strip()


def _retry_after(headers: Any) -> float | None:
    """Seconds from a numeric Retry-After header, capped. HTTP dates and junk are ignored."""
    value = headers.get("Retry-After") if headers is not None else None
    try:
        seconds = float(value)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(seconds) or seconds < 0:
        return None
    return min(seconds, MAX_RETRY_DELAY_SECONDS)


def _rotates(status: int | None) -> bool:
    return status is not None and (status in (401, 403, 429) or 500 <= status <= 599)


def _backs_off(status: int | None) -> bool:
    return status is not None and (status == 429 or 500 <= status <= 599)


def _backoff_delay(exc: NimRequestError) -> float:
    delay = exc.retry_after if exc.retry_after is not None else RETRY_DELAY_SECONDS
    return min(max(delay, 0.0), MAX_RETRY_DELAY_SECONDS)


def generate(mode: str, transcript: str, keys: list[tuple[str, str]],
             sleep: Callable[[float], None] | None = None) -> str:
    """Try the keys in order. Only throttling, refusal and server errors move on to the next key.

    A 429 or 5xx waits before the next key (Retry-After, capped, or 1 second), so the keys are not burned in
    milliseconds. The sleep function is injectable so tests do not wait.
    """
    if not keys:
        raise NimRequestError(None, NO_KEY_REASON)
    pause = sleep or time.sleep
    messages = build_messages(mode, transcript)
    refusal: NimRequestError | None = None
    for position, (name, key) in enumerate(keys):
        try:
            text = send_chat(key, messages)
        except NimRequestError as exc:
            if not _rotates(exc.status):
                raise
            logger.warning("AI mode %s: %s was refused (HTTP %s); trying the next key", mode, name, exc.status)
            refusal = exc
            if position + 1 < len(keys) and _backs_off(exc.status):
                pause(_backoff_delay(exc))
            continue
        logger.info("AI mode %s completed using %s", mode, name)
        return text
    status = refusal.status if refusal else None
    raise NimRequestError(status, f"NVIDIA NIM did not accept any configured key (last HTTP {status}). "
                                  "Try again later, or check the keys in .env.")
